<?php require_once dirname(__DIR__,2).'/bootstrap.php';require_post();$me=require_auth();$kind=$_POST['kind']??'';$token=(string)($_POST['uploadId']??'');$index=(int)($_POST['chunkIndex']??-1);$count=(int)($_POST['totalChunks']??0);$limits=['clip'=>500*1048576,'post'=>80*1048576,'photo'=>8*1048576];if(!isset($limits[$kind])||!preg_match('/^[a-zA-Z0-9_-]{16,64}$/D',$token)||$count<1||$count>512||$index<0||$index>=$count)json_response(['message'=>'Geçersiz yükleme.'],400);$saved=v17_query('SELECT response_json FROM mutation_receipts WHERE user_id=? AND request_key=? AND operation=?',[(int)$me['id'],$token,$kind==='clip'?'upload.clip':'upload.post'])->fetchColumn();if($saved){$d=json_decode($saved,true);$d['duplicate']=true;json_response($d);}if(($_FILES['chunk']['error']??4)!==0||($_FILES['chunk']['size']??0)>1048576)json_response(['message'=>'Dosya parçası yüklenemedi.'],413);$root=dirname(__DIR__,3).'/uploads/.chunks/u'.(int)$me['id'];if(!is_dir($root))mkdir($root,0770,true);foreach(glob($root.'/*')?:[] as $old)if(is_file($old)&&filemtime($old)<time()-86400)@unlink($old);$used=0;foreach(glob($root.'/*.part')?:[] as $old)$used+=filesize($old);if($used>$limits[$kind]+1048576)json_response(['message'=>'Önce devam eden yüklemeyi tamamlayın.'],413);$base=$root.'/'.$kind.'_'.$token;$lock=fopen($base.'.lock','c');if(!$lock||!flock($lock,LOCK_EX))json_response(['message'=>'Tekrar deneyin.'],503);$signature=hash('sha256',json_encode([$kind,$count,$_POST['title']??'',$_POST['description']??'',$_POST['body']??'']));if(is_file($base.'.json')&&file_get_contents($base.'.json')!==$signature)json_response(['message'=>'Yükleme bilgileri değişmiş.'],409);file_put_contents($base.'.json',$signature);if(!move_uploaded_file($_FILES['chunk']['tmp_name'],$base.'.'.$index.'.part'))json_response(['message'=>'Dosya yazılamadı.'],500);if($index<$count-1)json_response(['received'=>$index+1,'total'=>$count]);$total=0;for($i=0;$i<$count;$i++){if(!is_file($base.'.'.$i.'.part'))json_response(['mess